    {"effervescence": "effervescence / vitality", "foyers": "hotbeds / hubs", "parlements": "parliaments", "illustres": "illustrious", "ferveur": "fervor / passion", "absolutisme": "absolutism", "orateurs": "orators / speakers", "existentialistes": "existentialist", "poêle": "stove / heater", "ambiance": "ambiance / atmosphere", "liberté d'expression": "freedom of speech", "refaire le monde": "to reshape the world / debate endlessly"},
